    function panel(px,py,pw,ph,curve){o+='<rect x="'+px+'" y="'+py+'" width="'+pw+'" height="'+ph+'" '+st+'/>'+(pw>16&&ph>16?'<rect x="'+(px+5)+'" y="'+(py+5)+'" width="'+(pw-10)+'" height="'+(ph-10)+'" '+in2+'/>':'')}
