    if(fm){o+='<rect x="'+(vx-W(150))+'" y="'+(gy-W(g.vh)-W(150))+'" width="'+W(g.vw+300)+'" height="'+(W(g.vh)+W(150))+'" fill="#f1efea"/>';}
