      var q=norm(i.value.trim());if(q.length<2){f.classList.remove('open');return}
      var words=q.split(/\s+/);
      var res=P.filter(function(p){var h=norm(p.name+' '+(p.desc||'')+' '+(p.tags||[]).join(' ')+' '+catName(p.cat));return words.every(function(w){return h.indexOf(w)>=0})}).slice(0,7);
      box.innerHTML=res.length?res.map(function(p){return '<a href="?p='+esc(p.id)+'" data-s="'+esc(p.id)+'"><img '+imgAttrs(p)+' alt=""><span><b>'+esc(p.name)+'</b><small>'+esc(catName(p.cat))+'</small></span><em>'+priceTxt(p)+'</em></a>'}).join(''):'<p>没有找到与「'+esc(i.value)+'」相关的产品。试试「床头柜」「喷漆门」或「台面」。</p>';
